/**
 * ARCHITECTURE DOCUMENTATION: MockCopilotProxy
 * =============================================
 *
 * This file provides a mock implementation of the CopilotProxy for testing
 * and development in non-Electron environments (web browser, tests).
 *
 * ## Purpose:
 * - Allows the CopilotChatPanel to render and be tested in web builds
 * - Provides simulated responses for UI development
 * - Enables Playwright testing of the chat interface
 *
 * ## Usage:
 * The CopilotChatPanel checks CopilotProxy.isAvailable. When running in web,
 * this returns false. The panel can optionally use MockCopilotProxy to
 * simulate responses for development/testing.
 *
 * ## Related Files:
 * - src/core/CopilotProxy.ts - Real IPC-based implementation
 * - src/core/IChatSession.ts - Type definitions
 * - src/UX/CopilotChatPanel.tsx - React chat UI
 */

import { EventDispatcher } from "ste-events";
import { ICopilotAuthStatus, ICopilotModel, IChatEntry, IProjectSchemaSummary } from "./IChatSession";
import Utilities from "./Utilities";

/**
 * Mock responses for simulating Copilot behavior during development.
 */
const MOCK_RESPONSES: Record<string, string> = {
  default: "I'm a mock Copilot response for testing. In the Electron app, I would connect to the real Copilot SDK.",
  create:
    'I\'ll help you create that Minecraft content! Let me use the `createMinecraftContent` tool...\n\n```json\n{\n  "schemaVersion": "1.0.0",\n  "namespace": "my_addon",\n  "entityTypes": [...]\n}\n```',
  preview: "I'll generate a preview of that model for you using `previewModelDesign`...",
  help: "I can help you with:\n- Creating entities, blocks, and items\n- Previewing 3D models\n- Validating your content\n- Generating textures\n\nWhat would you like to do?",
};

/**
 * Mock implementation of CopilotProxy for web/test environments.
 */
export default class MockCopilotProxy {
  private static _onMessageDelta = new EventDispatcher<string, string>();
  private static _onMessage = new EventDispatcher<string, IChatEntry>();
  private static _onToolStart = new EventDispatcher<
    string,
    { toolCallId: string; toolName: string; argsJson: string }
  >();
  private static _onToolEnd = new EventDispatcher<
    string,
    { toolCallId: string; toolName: string; resultJson: string; success: boolean }
  >();
  private static _onSessionIdle = new EventDispatcher<string, void>();
  private static _onContextUpdated = new EventDispatcher<string, void>();
  private static _onError = new EventDispatcher<string, string>();

  private static _mockSessions: Map<string, { messages: IChatEntry[]; context?: IProjectSchemaSummary }> = new Map();
  private static _nextSessionId = 1;
  private static _simulateDelay = true;

  // Event accessors (mirror CopilotProxy API)
  public static get onMessageDelta() {
    return this._onMessageDelta.asEvent();
  }

  public static get onMessage() {
    return this._onMessage.asEvent();
  }

  public static get onToolStart() {
    return this._onToolStart.asEvent();
  }

  public static get onToolEnd() {
    return this._onToolEnd.asEvent();
  }

  public static get onSessionIdle() {
    return this._onSessionIdle.asEvent();
  }

  public static get onContextUpdated() {
    return this._onContextUpdated.asEvent();
  }

  public static get onError() {
    return this._onError.asEvent();
  }

  /**
   * Mock is always "available" for testing.
   */
  public static get isAvailable(): boolean {
    return true;
  }

  /**
   * Configure whether to simulate realistic delays.
   */
  public static set simulateDelay(value: boolean) {
    this._simulateDelay = value;
  }

  /**
   * Initialize the mock (no-op, but mirrors real API).
   */
  public static init(): void {
    // No-op for mock
  }

  /**
   * Simulated start - always succeeds.
   */
  public static async start(): Promise<boolean> {
    if (this._simulateDelay) {
      await this._delay(100);
    }
    return true;
  }

  /**
   * Get mock auth status - simulates authenticated state.
   */
  public static async getAuthStatus(): Promise<ICopilotAuthStatus> {
    return {
      isAuthenticated: true,
      login: "mock-user",
    };
  }

  /**
   * Get mock models list.
   */
  public static async listModels(): Promise<ICopilotModel[]> {
    return [
      { id: "gpt-4o", name: "GPT-4o", isDefault: true },
      { id: "gpt-4o-mini", name: "GPT-4o Mini", isDefault: false },
      { id: "claude-sonnet", name: "Claude Sonnet", isDefault: false },
    ];
  }

  /**
   * Create a mock session.
   */
  public static async createSession(options?: { model?: string }): Promise<string> {
    if (this._simulateDelay) {
      await this._delay(50);
    }

    const sessionId = `mock-session-${this._nextSessionId++}`;
    this._mockSessions.set(sessionId, { messages: [] });
    return sessionId;
  }

  /**
   * Update session context (mock implementation).
   */
  public static async updateContext(sessionId: string, context: IProjectSchemaSummary): Promise<void> {
    const session = this._mockSessions.get(sessionId);
    if (session) {
      session.context = context;
      this._onContextUpdated.dispatch(sessionId, undefined);
    }
  }

  /**
   * Send a message and simulate a response.
   */
  public static async send(sessionId: string, content: string): Promise<void> {
    const session = this._mockSessions.get(sessionId);
    if (!session) {
      this._onError.dispatch(sessionId, "Session not found");
      return;
    }

    // Add user message
    const userMessage: IChatEntry = {
      id: Utilities.createUuid(),
      role: "user",
      content,
      timestamp: new Date(),
    };
    session.messages.push(userMessage);
    this._onMessage.dispatch(sessionId, userMessage);

    // Determine mock response
    const lowerContent = content.toLowerCase();
    let response = MOCK_RESPONSES.default;
    if (lowerContent.includes("create") || lowerContent.includes("make")) {
      response = MOCK_RESPONSES.create;
    } else if (lowerContent.includes("preview") || lowerContent.includes("show")) {
      response = MOCK_RESPONSES.preview;
    } else if (lowerContent.includes("help") || lowerContent.includes("what can")) {
      response = MOCK_RESPONSES.help;
    }

    // Simulate streaming response
    if (this._simulateDelay) {
      await this._simulateStreamingResponse(sessionId, response);
    } else {
      const assistantMessage: IChatEntry = {
        id: Utilities.createUuid(),
        role: "assistant",
        content: response,
        timestamp: new Date(),
      };
      session.messages.push(assistantMessage);
      this._onMessage.dispatch(sessionId, assistantMessage);
    }

    this._onSessionIdle.dispatch(sessionId, undefined);
  }

  /**
   * Get messages for a session.
   */
  public static getSessionMessages(sessionId: string): IChatEntry[] {
    const session = this._mockSessions.get(sessionId);
    return session?.messages ?? [];
  }

  /**
   * End a mock session.
   */
  public static async endSession(sessionId: string): Promise<void> {
    this._mockSessions.delete(sessionId);
  }

  /**
   * Simulate a streaming response with realistic timing.
   */
  private static async _simulateStreamingResponse(sessionId: string, fullResponse: string): Promise<void> {
    const session = this._mockSessions.get(sessionId);
    if (!session) return;

    // Simulate tool call for certain responses
    if (fullResponse.includes("tool")) {
      const toolStart = {
        toolCallId: `mock-tool-${Date.now()}`,
        toolName: "previewModelDesign",
        argsJson: JSON.stringify({ design: { identifier: "mock_entity" } }),
      };
      this._onToolStart.dispatch(sessionId, toolStart);

      await this._delay(500);

      const toolEnd = {
        toolCallId: toolStart.toolCallId,
        toolName: toolStart.toolName,
        resultJson: JSON.stringify({ success: true, message: "Preview generated" }),
        success: true,
      };
      this._onToolEnd.dispatch(sessionId, toolEnd);
    }

    // Stream the response character by character (in chunks)
    const words = fullResponse.split(" ");

    for (let i = 0; i < words.length; i++) {
      this._onMessageDelta.dispatch(sessionId, words[i] + " ");
      await this._delay(30 + Math.random() * 50);
    }

    // Complete message
    const assistantMessage: IChatEntry = {
      id: Utilities.createUuid(),
      role: "assistant",
      content: fullResponse,
      timestamp: new Date(),
    };
    session.messages.push(assistantMessage);
    this._onMessage.dispatch(sessionId, assistantMessage);
  }

  private static _delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}
